-- Phase 3/4 additive migration. Backup and PRAGMA integrity_check before execution.
CREATE TABLE IF NOT EXISTS purchase_orders(po_id INTEGER PRIMARY KEY AUTOINCREMENT,po_number TEXT UNIQUE NOT NULL,station_id INTEGER NOT NULL,supplier_id INTEGER,status TEXT NOT NULL DEFAULT 'draft',expected_at TEXT,total_amount REAL NOT NULL DEFAULT 0,created_by INTEGER,approved_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_order_lines(line_id INTEGER PRIMARY KEY AUTOINCREMENT,po_id INTEGER NOT NULL REFERENCES purchase_orders(po_id) ON DELETE CASCADE,item_type TEXT NOT NULL,item_id INTEGER NOT NULL,quantity REAL NOT NULL,unit_price REAL NOT NULL DEFAULT 0,received_quantity REAL NOT NULL DEFAULT 0,invoice_quantity REAL NOT NULL DEFAULT 0,movement_quantity REAL NOT NULL DEFAULT 0,batch_id INTEGER,notes TEXT);
CREATE INDEX IF NOT EXISTS idx_phase3_po_station_status ON purchase_orders(station_id,status);
CREATE TABLE IF NOT EXISTS events_outbox(event_id INTEGER PRIMARY KEY AUTOINCREMENT,event_type TEXT NOT NULL,payload TEXT NOT NULL,consumer TEXT NOT NULL DEFAULT 'stock-levels',status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,available_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TEXT,delivered_at TEXT,last_error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_phase3_events_pending ON events_outbox(consumer,status,available_at,event_id);
CREATE TABLE IF NOT EXISTS inventory_forecasts(forecast_id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL,item_type TEXT NOT NULL,item_id INTEGER NOT NULL,forecast_date TEXT NOT NULL,demand_quantity REAL NOT NULL DEFAULT 0,days_of_cover REAL,reorder_quantity REAL NOT NULL DEFAULT 0,method TEXT NOT NULL DEFAULT 'LOCAL_MOVING_AVERAGE',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(station_id,item_type,item_id,forecast_date));
CREATE TABLE IF NOT EXISTS inventory_anomalies(anomaly_id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL,item_type TEXT NOT NULL,item_id INTEGER NOT NULL,anomaly_type TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'warning',metric_value REAL,threshold_value REAL,status TEXT NOT NULL DEFAULT 'OPEN',details TEXT,detected_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_health_snapshots(snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL,health_score REAL NOT NULL,low_stock_ratio REAL NOT NULL DEFAULT 0,dead_stock_ratio REAL NOT NULL DEFAULT 0,variance_avg_pct REAL NOT NULL DEFAULT 0,expiring_soon_ratio REAL NOT NULL DEFAULT 0,calculated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fuel_temperature_coefficients(fuel_type_id INTEGER PRIMARY KEY,coefficient_exp REAL NOT NULL DEFAULT 0.00095,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_scopes(user_id INTEGER NOT NULL,station_id INTEGER NOT NULL,role_code TEXT NOT NULL,can_read INTEGER NOT NULL DEFAULT 1,can_approve INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,station_id,role_code));
